LOCK TABLE speed_reading.exercises IN SHARE ROW EXCLUSIVE MODE;
LOCK TABLE speed_reading.reading_texts IN SHARE ROW EXCLUSIVE MODE;
CREATE TEMP TABLE guided_patch ON COMMIT DROP AS
SELECT (item->>'id')::uuid id, (item->>'ageGroupId')::uuid age_id,
 (item->>'level')::int level, item->>'title' title,
