FROM jsonb_array_elements($settings$[{"id":"aff1baaa-fc6b-5870-aaea-0013fb287d0d","age":"Child","ageGroupId":"10000000-0000-0000-0000-000000000001","level":1,"title":"Tanıdık Kelimelerle Okuma","minMinutes":2,"maxMinutes":3,"previousConfiguration":{"engineType":"word_highlight","engineConfig":{"content":{"source":"reading_text"},"mode":"guided","pacer":{"speedWpm":100,"chunkSize":1},"readingPurpose":"practice"},"difficultyLevel":1},"configuration":{"engineType":"word_highlight","difficultyLevel":1,"engineConfig":{"mode":"speed_reading","readingPurpose":"practice","content":{"source":"reading_text","minWordCount":200,"maxWordCount":300},"pacer":{"speedWpm":100,"chunkSize":1,"autoScroll":true},"adaptive":{"enabled":false}}}},{"id":"1c058d30-e5b1-5a67-85a8-a518b067a746","age":"Child","ageGroupId":"10000000-0000-0000-0000-000000000001","level":2,"title":"Akıcı Cümleler","minMinutes":2,"maxMinutes":3,"previousConfiguration":{"engineType":"word_highlight","engineConfig":{"content":{"source":"reading_text"},"mode":"guided","pacer":{"speedWpm":130,"chunkSize":1},"readingPurpose":"practice"},"difficultyLevel":2},"configuration":{"engineType":"word_highlight","difficultyLevel":2,"engineConfig":{"mode":"speed_reading","readingPurpose":"practice","content":{"source":"reading_text","minWordCount":260,"maxWordCount":390},"pacer":{"speedWpm":130,"chunkSize":1,"autoScroll":true},"adaptive":{"enabled":false}}}},{"id":"9bc800bb-a551-5ead-9fa3-7c406c33fffc","age":"Child","ageGroupId":"10000000-0000-0000-0000-000000000001","level":3,"title":"Akıcı Paragraflar","minMinutes":2,"maxMinutes":3,"previousConfiguration":{"engineType":"word_highlight","engineConfig":{"content":{"source":"reading_text"},"mode":"guided","pacer":{"speedWpm":160,"chunkSize":1},"readingPurpose":"practice"},"difficultyLevel":3},"configuration":{"engineType":"word_highlight","difficultyLevel":3,"engineConfig":{"mode":"speed_reading","readingPurpose":"practice","content":{"source":"reading_text","minWordCount":320,"ma