":4,"previousConfiguration":{"engineType":"word_highlight","engineConfig":{"content":{"source":"reading_text"},"mode":"guided","pacer":{"speedWpm":260,"chunkSize":1},"readingPurpose":"practice"},"difficultyLevel":3},"configuration":{"engineType":"word_highlight","difficultyLevel":3,"engineConfig":{"mode":"speed_reading","readingPurpose":"practice","content":{"source":"reading_text","minWordCount":780,"maxWordCount":1040},"pacer":{"speedWpm":260,"chunkSize":1,"autoScroll":true},"adaptive":{"enabled":false}}}},{"id":"84f9f28f-5823-5057-ae6a-600c7669d75c","age":"Adult","ageGroupId":"10000000-0000-0000-0000-000000000003","level":4,"title":"Dengeli Tempoda Okuma","minMinutes":3,"maxMinutes":4,"previousConfiguration":{"engineType":"word_highlight","engineConfig":{"content":{"source":"reading_text"},"mode":"guided","pacer":{"speedWpm":290,"chunkSize":1},"readingPurpose":"practice"},"difficultyLevel":4},"configuration":{"engineType":"word_highlight","difficultyLevel":4,"engineConfig":{"mode":"speed_reading","readingPurpose":"practice","content":{"source":"reading_text","minWordCount":870,"maxWordCount":1160},"pacer":{"speedWpm":290,"chunkSize":1,"autoScroll":true},"adaptive":{"enabled":false}}}},{"id":"c8b1179f-f752-54bb-a888-1c91793f8bdd","age":"Adult","ageGroupId":"10000000-0000-0000-0000-000000000003","level":5,"title":"Dengeli Tempoda Okuma","minMinutes":3,"maxMinutes":4,"previousConfiguration":{"engineType":"word_highlight","engineConfig":{"content":{"source":"reading_text"},"mode":"guided","pacer":{"speedWpm":320,"chunkSize":1},"readingPurpose":"practice"},"difficultyLevel":5},"configuration":{"engineType":"word_highlight","difficultyLevel":5,"engineConfig":{"mode":"speed_reading","readingPurpose":"practice","content":{"source":"reading_text","minWordCount":960,"maxWordCount":1280},"pacer":{"speedWpm":320,"chunkSize":1,"autoScroll":true},"adaptive":{"enabled":false}}}}]$settings$::jsonb) item;
CREATE TEMP TABLE guided_content_payload ON COMMIT DROP AS
SELECT item FROM jsonb_array_elements($content$[{"id":"61000000-0000-4000-8000-000000000001","exerciseId":"aff1baaa-fc6b-5870-aaea-0013fb287d0d","age":"Child","level":1,"title":"Parktaki Harita","file":"child-1-map.txt","content":"Elif, cumartesi sabahı dedesiyle parka gitti. Yanına küçük bir defter ve kırmızı bir kalem almıştı. Parkın kapısında eski bir harita vardı. Haritada oyun alanı, gölet ve yürüyüş yolu gösteriliyordu. Elif, haritaya bakınca bir şey fark etti. Yeni yapılan çeşme çizimde yoktu.\n\nDedesi, önce çevreye dikkatle bakmasını önerdi. Elif kapıdan çeşmeye kadar yürüdü. Sonra geri döndü ve defterine bir çizgi çizdi. Çeşmenin yanına küçük bir damla işareti koydu. Bu işaretin ne anlama geldiğini sayfanın altına yazdı. Artık çizime bakan biri çeşmeyi kolayca bulabilirdi.\n\nBiraz ileride iki yol ayrılıyordu. Soldaki yol gölete, sağdaki yol oyun alanına gidiyordu. Elif iki yolu da çizdi. Çizimin güzel görünmesinden çok doğru olmasını istiyordu. Bu yüzden ağacın arkasında kalan bankı da ekledi. Bank, uzaktan bakınca görünmüyordu ama yürüyen biri orada dinlenebilirdi.\n\nÇalışmasını bitirince dedesine haritayı verdi. Dedesi yalnız çizime bakarak çeşmeye ulaşmaya çalıştı. İlk denemede yanlış yola saptı. Elif, yol ayrımını yeterince açık göstermediğini anladı. İki çizginin arasını açtı ve oyun alanına bir top resmi ekledi.\n\nİkinci denemede dedesi doğru yere ulaştı. Elif bu kez haritanın gerçekten işe yaradığını gördü. Eve dönerken defterini çantasına yerleştirdi. Ertesi gün aynı çizimi arkadaşına da gösterecekti. Bir yerin haritasını yapmak için her ayrıntıyı çizmek gerekmiyordu. Önemli olan, yolu bulmaya yardım eden işaretleri doğru seçmekti. Elif bunu kendi küçük denemesiyle öğrenmişti."},{"id":"61000000-0000-4000-8000-000000000002","exerciseId":"aff1baaa-fc6b-5870-aaea-0013fb287d0d","age":"Child","level":1,"title":"Tohum Defteri","file":"child-1-seed.txt","content":"Deniz'in öğretmeni sınıfa üç küçük saksı getirdi. Her saksının içinde aynı türden bir tohum vardı. Öğretmen, bitkilerin büyümesini birlikte izleyeceklerini söyledi. Deniz bu görev için bir gözlem defteri hazırladı. İlk sayfaya tarihi yazdı ve saksıların resmini çizdi.\n\nSaksılar pencerenin önüne yerleştirildi. Üzerlerine bir, iki ve üç yazan etiketler yapıştırıldı. Böylece çocuklar hangi saksıya baktıklarını karıştırmayacaktı. Öğretmen sulama işini sırayla paylaştırdı. Deniz'in görevi her sabah toprağa bakmak ve gördüklerini not etmekti.\n\nİlk gün hiçbir değişiklik yoktu. İkinci gün de toprak aynı görünüyordu. Deniz, defterine yazacak bir şey bulamadığını düşündü. Öğretmeni, değişiklik olmamasının da bir gözlem olduğunu anlattı. Deniz bunun üzerine kısa bir cümle yazdı: Bugün henüz filiz görünmedi.\n\nDördüncü sabah birinci saksıda küçücük bir yeşillik belirdi. Deniz hemen diğer saksılara baktı. Onlarda henüz filiz yoktu. Üç saksının aynı anda büyümesi gerektiğini sanmıştı. Öğretmeni, canlıların gelişiminin her zaman aynı hızda ilerlemediğini söyledi. Çocuklar gözlem yapmaya devam etti.\n\nHaftanın sonunda her saksıda bir filiz vardı. Deniz, önceki çizimleriyle son çizimini karşılaştırdı. Küçük farkları artık daha kolay görebiliyordu. Yaprakların sayısını yazdı ama henüz ölçmediği boyları tahmin ederek doldurmadı. Bir sonraki hafta cetvel kullanacaklardı.\n\nDefterini kapatırken yaptığı işin yalnız bitki yetiştirmek olmadığını fark etti. Dikkatle bakmayı, sabretmeyi ve bilmediği bir şeyi biliyormuş gibi yazmamayı da öğreniyordu. Üç küçük saksı, sınıfın her sabah merakla kontrol ettiği bir köşeye dönüşmüştü."},{"id":"61000000-0000-4000-8000-000000000003","exerciseId":"030538ee-839b-56c6-a3a2-2d9a78ead0d7","age":"Child","level":4,"title":"Kütüphanenin Onarım Masası","file":"child-4-library.txt","content":"Mahalle kütüphanesinde küçük bir onarım masası kurulmuştu. Masanın üzerinde yıpranmış kitaplar, boş kâğıtlar ve renkli ayraçlar duruyordu. Ada ile Eren, görevli Selin Hanım'ın yanında gönüllü olarak çalışacaktı. İlk bakışta işin yalnızca kopan kapakları yapıştırmak olduğunu sandılar. Oysa masanın kenarında farklı sorunları anlatan bir liste vardı.\n\nBazı kitapların sayfaları gevşemişti. Bazılarının sırtındaki etiket okunmuyordu. Birkaç kitabın içinde de önceki okuyucuların unuttuğu notlar bulunuyordu. Selin Hanım, her kitaba aynı işlemi uygulayamayacaklarını açıkladı. Önce sorunu belirlemek, sonra uygun işlem için görevliden yardım istemek gerekiyordu. Çocuklar kendi başlarına eski bir kitabı sökmeyecekti.\n\nAda, eline aldığı ilk kitabın kapağını dikkatle açtı. İçindeki sayfalar sağlamdı ama dış etiket silinmişti. Kitabın adını listeye yazdı ve yeni etiket hazırlanacak bölüme bıraktı. Eren'in kitabında ise aynı sayfa iki kez görünüyordu. Bunun bir basım hatası mı, yoksa sonradan eklenmiş bir kâğıt mı olduğunu anlayamadı. Tahmin etmek yerine sorusunu not etti.\n\nGörevli, iki işlemin neden farklı olduğunu gösterdi. Etiket değiştirmek kolaydı; sayfaların sırasına müdahale etmek ise kitabın bütünlüğünü etkileyebilirdi. Çocuklar böylece hızlı çalışmanın tek başına yeterli olmadığını gördü. Yapılan işin geri alınabilir olması ve kitabı yanlış değiştirmemesi de önemliydi. Emin olmadıkları kitaplar için ayrı bir kutu hazırladılar.\n\nÖğleden sonra onarım masasının yanında ayraç atölyesi başladı. Ada, hazırlanan ayraçların üzerine uzun uyarılar yazmak istedi. Eren ise tek bir resmin yeterli olacağını düşündü. İkisi de kendi tasarımını yaptı. Sonra kütüphaneye gelen birkaç kişiye ayraçları gösterdiler. İnsanların hangi mesajı daha kolay anladığını sordular ve cevapları defterlerine kaydettiler.\n\nBir çocuk, resimdeki katlanmış köşenin ne anlama geldiğini anlamadı. Başka biri uzun yazıyı okumadan geçti. Ada ile Eren, resmi kısa bir cümleyle birleştirmeye karar verdi. Yeni ayraçta, sayfa köşesini katlamak yerine ayraç kullanılması öneriliyordu. Böylece hem çizim hem yazı aynı amaca hizmet etti. İlk tasarımlarını çöpe atmadılar; karşılaştırmak için sakladılar.\n\nGünün sonunda Selin Hanım, tamamlanan işleri birlikte saymalarını istedi. Çocuklar onarılan kitapları, yenilenen etiketleri ve inceleme bekleyen kitapları ayrı ayrı yazdı. İnceleme kutusunu bitmiş işler arasında göstermediler. Henüz çözülemeyen bir sorunu açıkça belirtmek, başarısız oldukları anlamına gelmiyordu. Sonraki görevlinin nereden devam edeceğini bilmesini sağlıyordu.\n\nMasayı toplamadan önce bütün araçların yerini kontrol ettiler. Kullanılmayan kâğıtları bir kutuya, hazırlanmış ayraçları başka bir kutuya koydular. Her kutuya kısa bir etiket eklediler. Sonraki gönüllülerin aynı düzeni kolayca anlayabilmesi için masanın çizimini de deftere yapıştırdılar.\n\nAda eve dönerken küçük masanın kendisine öğrettiği şeyleri düşündü. Dikkat, yalnız bir nesneye uzun süre bakmak değildi. Ayrıntıları ayırt etmek, gerektiğinde soru sormak ve yapılan işi kontrol etmek de dikkat gerektiriyordu. Eren ise sonraki hafta için farklı boylarda ayraçlar tasarlamaya karar verdi. Kütüphane artık onlar için yalnız kitap ödünç alınan bir yer değil, birlikte düşünerek sorun çözülen bir çalışma alanıydı."},{"id":"61000000-0000-4000-8000-000000000004","exerciseId":"030538ee-839b-56c6-a3a2-2d9a78ead0d7","age":"Child","level":4,"title":"Yağmurun İzleri","file":"child-4-rain.txt","content":"Gece boyunca yağmur yağmıştı. Sabah okul bahçesine çıkan öğrenciler, bazı yerlerde su biriktiğini gördü. Bahçenin bir köşesi çabuk kururken girişe yakın bölüm hâlâ ıslaktı. Öğretmenleri bu farkı incelemek için küçük bir gözlem çalışması önerdi. Amaç, bahçenin hangi noktalarında suyun daha uzun süre kaldığını bulmaktı. Çocuklar bir çözüm düşünmeden önce ne olduğunu anlamaya çalışacaktı.\n\nMert, bahçenin basit bir krokisini çizdi. Zeynep, su biriken yerlerin fotoğraflarını öğretmenin cihazıyla kaydetti. Diğer öğrenciler gözlem saatini ve hava durumunu not etti. Güvenli olmayan ıslak bölümlere girmediler. Yalnızca belirlenen yoldan bakarak çalıştılar. Öğretmen, iyi bir gözlem yapmak için tehlikeli bir yere yaklaşmak gerekmediğini hatırlattı.\n\nİlk gözlemde üç büyük su birikintisi vardı. Çocuklar bunlara aynı adları vermek için krokide harf kullandı. Girişteki birikinti A, ağacın yanındaki B, duvarın yakınındaki ise C oldu. Böylece öğleden sonra tekrar baktıklarında hangi noktayı karşılaştırdıklarını anlayabileceklerdi. Birikintinin yalnız büyüklüğüne değil, çevresindeki zemine de dikkat ettiler.\n\nÖğle saatinde B noktasındaki su azalmıştı. A noktasında ise belirgin bir değişiklik görünmüyordu. Mert, ağacın bütün suyu emdiğini düşündü. Zeynep bunun henüz kanıtlanmadığını söyledi. Güneş, rüzgâr ve zeminin eğimi de fark yaratmış olabilirdi. Öğretmenleri, tek bir gözlemden kesin sonuç çıkarmak yerine olası açıklamaları ayrı bir sütuna yazmalarını istedi.\n\nErtesi gün çocuklar aynı saatlerde yeniden gözlem yaptı. Bu kez güneş daha uzun süre görünüyordu. Bir önceki günün fotoğraflarıyla yeni fotoğrafları yan yana koydular. Fotoğrafların farklı açıdan çekilmesi karşılaştırmayı zorlaştırmıştı. Sonraki çekimler için güvenli bir durma noktası seçtiler. Çalışmanın düzeni, ilk denemeden sonra daha açık hâle geldi.\n\nHafta sonunda sınıfta küçük bir toplantı yapıldı. Çocuklar, girişteki birikintinin iki farklı yağmurdan sonra da uzun süre kaldığını anlattı. Bunun nedenini tam olarak bilmediklerini özellikle belirttiler. Bahçenin bakımından sorumlu kişiye göstermek üzere bir sayfalık rapor hazırladılar. Rapora gözlem saatlerini, krokilerini ve seçtikleri fotoğrafları eklediler. Tahminleri ise gözlemlerden ayrı tuttular.\n\nBakım görevlisi raporu inceleyince girişteki zeminin kontrol edilmesi gerektiğini söyledi. Çocuklar kendi çalışmalarının hemen büyük bir inşaata dönüşmesini beklemiyordu. Yaptıkları şey, sorunun yerini ve ne zaman görüldüğünü açık biçimde göstermekti. Bu bilgi, sonraki incelemeyi kolaylaştırıyordu. Öğretmenleri, günlük bir sorunun bile dikkatli kayıt tutularak daha anlaşılır hâle getirilebileceğini açıkladı.\n\nRaporun bir kopyasını sınıfta sakladılar. Sonradan yapılacak bir düzenlemenin etkisini değerlendirmek için eski durumun kaydı gerekliydi. Öğrenciler bakım görevlisine ne zaman tekrar gözlem yapabileceklerini sordu. Güvenli çalışma alanı belirlendikten sonra aynı yöntemle yeni bilgiler toplayacaklardı.\n\nMert artık bir su birikintisine baktığında yalnız ıslak bir yer görmüyordu. Nerede oluştuğunu, ne kadar kaldığını ve hangi koşullarda değiştiğini düşünüyordu. Zeynep ise defterin en son sayfasına kısa bir not ekledi: İyi soru, hemen bulunan cevaptan önce gelir. İkisi de sonraki gözlem çalışmasında önce sorularını belirlemeye, sonra hangi bilgileri toplamaları gerektiğine karar vermeye hazırdı."},{"id":"61000000-0000-4000-8000-000000000005","exerciseId":"4230beb8-f60f-5c08-a757-acf22d0fa332","age":"Child","level":5,"title":"Köprü Maketinin Soruları","file":"child-5-bridge.txt","content":"Bilim kulübündeki öğrenciler, küçük bir köprü maketi tasarlamak için iki gruba ayrıldı. Masanın iki ucuna yerleştirilen desteklerin arasındaki boşluk herkes için aynıydı. Kullanılabilecek karton miktarı da sınırlıydı. Öğretmen, yarışmanın yalnız en çok ağırlığı taşıyan köprüyü bulmak olmadığını açıkladı. Gruplar, hangi değişikliğin neyi etkilediğini de anlatmalıydı. Bu nedenle çizimler, deneme sonuçları ve başarısız tasarımlar çalışma boyunca saklanacaktı.\n\nDuru'nun grubu önce düz bir karton parçasını desteklerin üzerine koydu. İlk küçük yükte karton aşağı doğru eğildi. Kerem hemen ikinci bir karton eklemek istedi. Duru ise önce ilk denemenin sonucunu kaydetmelerini önerdi. Yeni malzeme eklediklerinde ne kadar fark oluştuğunu ancak böyle anlayabilirlerdi. Defterde kullanılan karton miktarı, destekler arasındaki uzaklık ve yükün konduğu yer için ayrı satırlar açtılar.\n\nSonraki denemede aynı miktarda kartonu katlayarak kullandılar. Katların biçimi değişince köprünün görünümü de değişti. Ancak yükün yerini önceki denemeden farklı seçmişlerdi. Sonuç daha iyi görünse de bunun yalnız katlama biçiminden kaynaklandığını söyleyemediler. Öğretmenleri, bir karşılaştırmada koşulları mümkün olduğunca aynı tutmanın neden önemli olduğunu sordu. Öğrenciler ikinci tasarımı aynı noktadan yükleyerek yeniden denedi.\n\nDiğer grup kartondan üçgen destekler hazırlıyordu. Kerem onların tasarımına bakınca kendi köprülerinin yanlış olduğunu düşündü. Duru, farklı bir tasarımın görülmesinin ilk çalışmayı değersiz yapmadığını söyledi. İki grup farklı yöntemlerle aynı soruna yaklaşıyordu. Sonuçları karşılaştırmak için malzeme miktarının ve deneme düzeninin açık olması gerekiyordu. Yalnız köprülerin fotoğraflarına bakarak hangisinin daha başarılı olduğunu anlamak mümkün değildi.\n\nÜçüncü tasarım hazırlanırken grubun içinde bir anlaşmazlık çıktı. Kerem, çok sayıda ince katın daha iyi olacağını savunuyordu. Duru ise az sayıda geniş katı denemek istiyordu. Tartışmayı tahminlerle sürdürmek yerine iki küçük örnek hazırladılar. Her örnek için aynı tür karton kullandılar ve yükü aynı noktaya koydular. Sonuçlardan biri beklentilerine uymadı. Bu şaşırtıcı farkı gizlemek yerine nedenini incelemek için işaretlediler.\n\nÖrneklerden birinin kenarı önceden yıpranmıştı. Ayrıca katlardan biri diğerlerine göre daha gevşekti. Çocuklar bu ayrıntıların sonucu etkileyebileceğini düşündü. Denemeyi yenilediklerinde fark azaldı. Böylece tek bir ölçümün her zaman yeterli olmadığını gördüler. Yine de sınıftaki küçük deneyden bütün köprüler için geçerli bir kural çıkaramazlardı. Kullandıkları malzeme, boyut ve yükler gerçek köprülerden çok farklıydı.\n\nSunum günü her grup yalnız son maketini değil, çalışma defterini de getirdi. Duru, ilk başarısız köprünün fotoğrafını özellikle gösterdi. Bu deneme, sonraki soruların oluşmasını sağlamıştı. Kerem ise karşılaştırma sırasında değiştirdikleri koşulları anlattı. En yüksek yükü taşıyan tasarımın neden işe yaradığını henüz bütünüyle açıklayamadıklarını söylediler. Açık bıraktıkları soruları sunumun sonuna eklediler.\n\nSunumdan sonra öğrenciler birbirlerinin defterlerini inceledi. Bazı çizimlerde ölçülerin eksik olduğunu, bazılarında ise deneme tarihinin yazılmadığını gördüler. Her grup, kendi kaydını başka birinin anlayıp anlayamadığını kontrol etti. Duru bir çizime yükün yerini gösteren ok ekledi. Kerem de kullanılan kartonun daha önce katlanıp katlanmadığını belirten yeni bir sütun hazırladı.\n\nKulüp çalışması sona erdiğinde masanın üzerinde birbirinden farklı köprüler vardı. Bazıları sağlam, bazıları hafif, bazıları ise kolay kuruluyordu. Öğrenciler bir tasarımı değerlendirirken tek bir özelliğe bakmanın yetersiz kalabileceğini fark etti. Bir amacın sınırlarını belirlemek, denemeyi doğru kurmak ve sonuçları dürüstçe anlatmak da yapılan işin parçasıydı. Duru defterini kapatmadan önce yeni bir soru yazdı: Aynı yöntem başka bir malzemeyle denenseydi sonuç nasıl değişirdi?"},{"id":"61000000-0000-4000-8000-000000000006","exerciseId":"4230beb8-f60f-5c08-a757-acf22d0fa332","age":"Child","level":5,"title":"Mahallenin Hafızası","file":"child-5-memory.txt","content":"Okulun yakınındaki eski çeşme yenilenirken öğrenciler mahallede küçük bir tarih çalışması yapmaya karar verdi. Çeşmenin ne zaman yapıldığını ve eskiden nasıl kullanıldığını öğrenmek istiyorlardı. Öğretmenleri, herkesin hatırasının aynı olmayabileceğini söyledi. Bir kişinin anlattığı olayı hemen kesin bilgi olarak yazmak yerine farklı kaynakları karşılaştıracaklardı. Çalışmanın amacı, mahalleyi tanımak kadar bilgi toplarken dikkatli davranmayı da öğrenmekti.\n\nİlk görüşme bakkalın sahibi Nihat Bey ile yapıldı. Nihat Bey, çocukken çeşmenin yanında bekleyen insanları hatırlıyordu. O yıllarda çevredeki bazı evlere su taşındığını anlattı. Ancak hangi yıldan söz ettiğini kesin olarak söyleyemedi. Öğrenciler notlarına yaklaşık bir tarih aralığı yazdı. Anlatılan olayla anlatıcının kendi tahmini aynı cümlede birbirine karışmasın diye defterde farklı işaretler kullandılar.\n\nİkinci görüşmede mahallede uzun süredir yaşayan Ayşe Hanım farklı bir ayrıntı paylaştı. Ona göre çeşmenin çevresinde küçük bir pazar kuruluyordu. Öğrenciler iki anlatının birbirini dışladığını düşündü. Öğretmenleri ise aynı yerin farklı zamanlarda farklı amaçlarla kullanılabileceğini hatırlattı. Çeşme, bir dönemde su taşınan bir nokta, başka bir dönemde buluşma yeri olmuş olabilirdi. Yeni sorularını zaman ve kullanım biçimi üzerine kurdular.\n\nDaha sonra okul arşivinde birkaç eski fotoğraf bulundu. Fotoğraflardan birinde çeşmenin arkasındaki dükkân görünüyordu ama çekim tarihi yazmıyordu. Başka bir fotoğrafın arkasında bir yıl vardı. Bu iki görüntüyü doğrudan aynı döneme ait saymak doğru olmazdı. Çocuklar dükkânın tabelasını, yolun biçimini ve çevredeki binaları karşılaştırdı. Bunlar tarih için ipucu olabilirdi; yine de tek başlarına kesin kanıt sayılmıyorlardı.\n\nGörüşmeler ilerledikçe çalışma defteri kalabalıklaştı. Öğrenciler anlatılan her ayrıntıyı sergiye koymak istedi. Fakat bazı sözler yalnız bir kişinin özel hayatıyla ilgiliydi. Öğretmenleri, insanların paylaşılmasını istemediği bilgileri sergilememeleri gerektiğini açıkladı. Bir anıyı dinlemek, onu her yerde yayımlama izni almak anlamına gelmiyordu. Çocuklar kullanılacak kısa alıntılar ve fotoğraflar için ayrıca izin istedi.\n\nSergi panosunu hazırlarken bilgileri üç bölüme ayırdılar. İlk bölümde tarihi bilinen fotoğraflar yer aldı. İkinci bölümde görüşmelerden izin alınmış hatıralar vardı. Son bölüm ise henüz cevabı bulunamayan sorulara ayrıldı. Birbiriyle uyuşmayan iki tarih silinmedi. Panoda bu tarihler hakkında farklı anlatılar bulunduğu açıkça yazıldı. Böylece sergiyi gezen kişiler de bilginin nasıl toplandığını görebilecekti.\n\nAçılış günü yeni bir ziyaretçi, evinde çeşmenin daha eski bir fotoğrafının bulunduğunu söyledi. Öğrenciler hemen bütün panoyu değiştirmek yerine fotoğrafı incelemek için yeni bir görüşme planladı. Çalışmaları tek bir günde tamamlanmış, değişmez bir hikâye değildi. Yeni bilgi geldikçe değerlendirmeleri güncellenebilirdi. Ancak her yeni ayrıntı aynı dikkatle kontrol edilmeli ve kaynağı not edilmeliydi.\n\nÇalışma grubunun son toplantısında her öğrenci araştırmanın bir güçlüğünü anlattı. Kimi eski yazıları okumakta, kimi görüşmelerde doğru soruyu seçmekte zorlanmıştı. Birlikte hazırladıkları kısa rehberde, yeni araştırmacılara önce izin almalarını, sonra kaynağı açıkça yazmalarını önerdiler. Kesin olmayan bilgilerin de uygun bir açıklamayla korunabileceğini belirttiler. Rehber, serginin yanında isteyenlerin okuyabileceği bir dosyaya yerleştirildi.\n\nÇeşme yenilendikten sonra çocuklar önünde toplu bir fotoğraf çektirdi. Bu kez çekim tarihini, fotoğrafın amacını ve paylaşım iznini kayıtlarına eklediler. İleride başka öğrenciler aynı yeri araştırırsa bu bilgilerin işlerini kolaylaştıracağını düşündüler. Mahallenin geçmişini öğrenirken kendilerinin de yeni bir kayıt oluşturduğunu fark etmişlerdi. İyi bir kayıt, yalnız güzel bir görüntüden değil, görüntünün neyi gösterdiğini açıklayan güvenilir bilgilerden oluşuyordu."},{"id":"61000000-0000-4000-8000-000000000007","exerciseId":"ef36a01a-8e60-563f-a8e8-6e58aa8a82d6","age":"Teen","level":5,"title":"Okul Rotası: Veriden Karara","file":"teen-5-route.txt","content":"Okulun öğrenci meclisi, sabah girişinde oluşan kalabalığı incelemek için bir çalışma grubu kurdu. İlk toplantıda herkes farklı bir çözüm önerdi. Bazıları kapının genişletilmesini, bazıları servislerin başka bir noktada durmasını istiyordu. Ancak önerilerin çoğu kişisel izlenimlere dayanıyordu. Grup, bir çözümü savunmadan önce sorunun hangi saatlerde ve nerelerde ortaya çıktığını anlamaya karar verdi. Öğretmenlerinin gözetiminde, yalnızca güvenli noktalardan ve kimlik bilgisi toplamadan gözlem yapacaklardı. Araştırmanın sınırlarını baştan yazmaları, sonraki kararları daha açık tartışmalarına yardımcı oldu.\n\nİlk hafta gözlemler üç farklı sabah yapıldı. Öğrenciler gelen kişilerin adlarını veya fotoğraflarını kaydetmedi. Bunun yerine belirli aralıklarla giriş önündeki yaklaşık yoğunluğu not etti. Havanın yağışlı olup olmadığını, bir servis aracının geç kalıp kalmadığını ve girişte özel bir etkinlik bulunup bulunmadığını da yazdılar. Böylece yalnız kişi sayısına bakılarak anlaşılmayabilecek durumları kayda geçirdiler. Bir ölçümün yanında koşulların bulunması, sayının tek başına her şeyi açıklamadığını gösteriyordu. Grup, eksik kalan gözlemleri tahmin ederek doldurmadı; bunları açıkça boş bıraktı.\n\nVeriler bir tabloya aktarıldığında ilk bakışta belirgin bir sonuç ortaya çıktı. En yoğun saat aralığı üç günün ikisinde aynıydı. Fakat üçüncü gün tablo farklı görünüyordu. Bir öğrenci o günü hatalı sayıp çıkarmayı önerdi. Diğerleri, farklılığın gerçekten önemli bir durumu göstermiş olabileceğini düşündü. Notları yeniden incelediklerinde o sabah bir yol çalışması nedeniyle servislerin farklı zamanda geldiğini gördüler. Bu kayıt silinmek yerine ayrı bir açıklamayla korundu. Normal koşullar ile beklenmeyen koşulların birlikte görülmesi, önerilecek düzenlemenin farklı günlerde nasıl işleyeceği hakkında yeni sorular doğurdu.\n\nGrup daha sonra okulun çevresine ilişkin yayımlanmış ulaşım bilgilerini incelemek istedi. Buldukları haritanın üzerinde güncelleme tarihi vardı, fakat bazı duraklar eski adlarıyla görünüyordu. Öğrenciler kaynağı kullanmadan önce hangi kısmının güncel olduğunu kontrol etti. İnternette kolayca bulunan bir bilgi, sırf bir haritada yer aldığı için doğru kabul edilemezdi. Özellikle güvenli ulaşım hakkında öneri hazırlanırken hatalı bir ayrıntı önemli sonuçlar doğurabilirdi. Çalışma grubunun hazırladığı belge bir yol güvenliği talimatı olmayacak; okul yönetiminin değerlendireceği gözlemleri ve soruları içerecekti.\n\nAnket hazırlama fikri gündeme geldiğinde yeni bir tartışma başladı. Öğrenciler herkesin ev adresini sorarak güzergâhları anlamayı düşündü. Öğretmenleri bunun amaç için gereksiz ayrıntı olabileceğini açıkladı. Bunun yerine yürüyerek, toplu taşımayla veya servisle gelenlerin genel deneyimleri sorulabilirdi. Yanıt vermek isteğe bağlı olmalı, kişisel bilgiler gereksiz yere toplanmamalıydı. Grup anketi kısalttı ve her sorunun neyi anlamaya yardım ettiğini yanına yazdı. Açık bir gerekçesi bulunmayan sorular çıkarıldı. Böylece daha çok bilgi toplamanın her zaman daha iyi araştırma anlamına gelmediğini fark ettiler.\n\nAnket sonuçlarıyla gözlemler aynı belgeye eklendiğinde iki veri türünün farklı şeyler anlattığı görüldü. Gözlemler belirli sabahların durumunu, anket ise yanıt verenlerin deneyimlerini gösteriyordu. Bunları aynı kesinlikte sonuçlar olarak sunmak doğru olmazdı. Örneğin ankete katılanların çoğu yürüyerek gelmişti; servis kullananların görüşleri daha az temsil ediliyordu. Öğrenciler bu sınırlılığı raporun başına yazdı. Sonuçları okulun tamamına ait değişmez bir gerçek gibi anlatmak yerine, mevcut çalışmanın kapsamını ve eksik kalan yönlerini açıkladılar. Belgenin anlaşılır olması için grafiklerin altına kısa açıklamalar eklediler.\n\nÖneri bölümünde tek bir çözüm yerine iki küçük deneme seçeneği hazırlandı. Bunların uygulanabilirliği okul yönetimi ve ilgili görevliler tarafından değerlendirilecekti. Her seçenek için beklenen yarar, olası güçlük ve tekrar gözlenmesi gereken durum yazıldı. Öğrenciler hangi ölçütün başarı sayılacağını da tartıştı. Kalabalığın azalması kadar, girişin herkes için erişilebilir kalması ve güvenliğin korunması da önemliydi. Yalnız en hızlı geçişi sağlayan düzen, diğer ihtiyaçları karşılamıyorsa yeterli olmayabilirdi. Bu nedenle çözümün tek bir sayıyla değerlendirilmemesi gerektiğini raporlarına eklediler.\n\nSunum sırasında yönetimden gelen sorular grubun bazı varsayımlarını yeniden düşünmesini sağladı. Gözlem süresi kısa olduğu için farklı mevsimlerde ne olacağını bilmiyorlardı. Ayrıca önerilerin görevli düzeni üzerindeki etkisini hesaplamamışlardı. Öğrenciler bilmedikleri noktaları savunmaya çalışmak yerine yeni inceleme başlıkları olarak kaydetti. Hazırladıkları çalışma doğrudan uygulanacak kesin bir plan değil, daha iyi karar verilmesine yardım eden bir başlangıçtı. Belirsizliği açıkça söylemek, yaptıkları işi zayıflatmıyordu; hangi kısmın gözleme, hangi kısmın tahmine dayandığını anlaşılır hâle getiriyordu.\n\nProjenin sonunda grup bütün kişisel veri içermeyen çalışma dosyalarını düzenledi. Kullanılan kaynakların bağlantıları ve erişim tarihleri bir sayfaya yazıldı. Düzeltilen grafiklerin eski sürümleri, neden değiştirildiklerini açıklayan notlarla saklandı. Sonraki öğrenci grubunun aynı soruları tekrar sormadan çalışmaya devam edebilmesini istiyorlardı. İlk toplantıda hızla çözüm öneren öğrenciler artık önce sorunun tanımını, ölçüm yöntemini ve verinin sınırlarını tartışıyordu. Bir okul girişini incelemek onlara yalnız tablo hazırlamayı değil, kanıt ile öneri arasındaki mesafeyi dikkatle korumayı da öğretmişti."},{"id":"61000000-0000-4000-8000-000000000008","exerciseId":"ef36a01a-8e60-563f-a8e8-6e58aa8a82d6","age":"Teen","level":5,"title":"Serginin Arkasındaki Seçimler","file":"teen-5-exhibition.txt","content":"Kent kütüphanesinde düzenlenecek öğrenci sergisinin konusu gündelik nesnelerin hikâyeleriydi. Katılımcılardan eski bir eşya seçmeleri, nereden geldiğini araştırmaları ve ziyaretçilere kısa bir anlatı sunmaları istenmişti. Defne büyükannesinin kullandığı bir radyo, Aras ise ailesinin yıllardır sakladığı bir tamir kutusu üzerinde çalışacaktı. İkisi de ilk toplantıda nesneleri hakkında çok şey bildiğini düşünüyordu. Fakat sergi metnini yazmaya başladıklarında hatırlanan olaylar, kişisel yorumlar ve doğrulanabilir bilgiler arasında önemli farklar bulunduğunu gördüler. Her cümlenin dayanağı aynı türden değildi.\n\nDefne, radyonun satın alındığı yılı öğrenmek için büyükannesiyle konuştu. Büyükannesi belirli bir yaz tatilini hatırlıyor, fakat tam tarihi söyleyemiyordu. Radyonun üzerindeki model adı başka bir başlangıç noktası sağladı. Defne bulduğu farklı kaynaklarda benzer görünümlü cihazların birbirine karıştırıldığını fark etti. Bu nedenle yalnız fotoğraf benzerliğine dayanarak tarih vermedi. Model bilgisini ve hatırayı ayrı ayrı yazdı. Kesinleşmeyen noktalar için yaklaşık ifadeler kullandı. Sergiyi gezen birinin, anlatının hangi kısmında belirsizlik bulunduğunu anlayabilmesi onun için önemliydi.\n\nAras'ın tamir kutusunda eksik parçalar vardı. Kutunun ilk hâlini gösteren bir fotoğraf bulunmadığı için hangi parçanın ne zaman kaybolduğunu bilmiyordu. Babası, kutuyu farklı zamanlarda farklı işlerde kullandıklarını anlattı. Aras başlangıçta kutuyu bir mesleğin eksiksiz temsilcisi olarak sunmayı planlamıştı. Ancak aileye ait tek bir örnekten bütün bir meslek hakkında sonuç çıkaramayacağını anladı. Anlatısını daha dar bir çerçeveye yerleştirdi: Bu kutunun aile içindeki kullanım hikâyesini gösterecekti. Kapsamı küçültmek, metnin daha dürüst ve anlaşılır olmasını sağladı.\n\nSergi hazırlık ekibi nesnelerin yanına konacak açıklamalar için ortak bir uzunluk önerdi. Amaç bütün ziyaretçilerin ayrıntılı bir araştırma dosyası okumasını beklemek değildi. Kısa bir ana metin, isteyenler için ise daha uzun bir kaynak dosyası hazırlanacaktı. Defne ilk taslağındaki bazı cümleleri çıkarırken yalnız metni kısaltmaya çalışmadı. Hangi bilginin ziyaretçinin nesneyi anlamasına gerçekten yardım ettiğini düşündü. Dikkat çekici ama konuyla ilgisi zayıf ayrıntıları ayrı dosyaya taşıdı. Başlıkların ve paragraf düzeninin de anlatının anlaşılmasını etkilediğini gördü.\n\nTasarım aşamasında görseller için izin konusu gündeme geldi. Öğrenciler aile fotoğraflarını kullanmak istiyordu, fakat fotoğrafta görünen herkes sergiye katılmamıştı. Öğretmenleri, bir fotoğrafın ellerinde bulunmasının onu herkese açık şekilde sergilemek için tek başına yeterli olmadığını hatırlattı. İzin verilmeyen görseller kullanılmadı; bazı nesneler yeniden fotoğraflandı. Yeni çekimlerde yalnız sergilenecek eşya yer aldı. Kaynak ve izin bilgileri hazırlık dosyasına eklendi. Böylece ziyaretçi açısından basit görünen bir görsel seçiminin arkasında da dikkatli kararlar bulunabileceği anlaşıldı.\n\nİlk deneme sergisine başka sınıflardan öğrenciler çağrıldı. Defne, ziyaretçilerin radyoya bakarken sorduğu soruları not etti. Bazıları teknik ayrıntıları merak ederken bazıları radyonun ailede kimler tarafından kullanıldığını öğrenmek istiyordu. Aras'ın açıklaması ise araçların adlarını bilmeyen ziyaretçiler için zor görünüyordu. İki öğrenci metinlerini yeniden düzenledi. Bilinmeyen sözcükler kısa açıklamalarla desteklendi. Ancak metni kolaylaştırmak için doğrulanmış bir bilgiyi değiştirip daha heyecanlı bir hikâye oluşturmadılar. Anlaşılır anlatım ile bilgiyi çarpıtmak arasındaki ayrımı korumaya çalıştılar.\n\nDeneme sırasında bir ziyaretçi, radyonun üzerinde yazan modelin açıklama dosyasındaki modelden farklı olduğunu söyledi. Defne ilk anda bütün araştırmasının yanlış olduğunu düşündü. Sonra kaynaklara geri dönerek küçük bir yazım hatası yaptığını buldu. Düzeltmeyi yalnız sergi kartında değil, kaynak dosyasında da yaptı. Değişikliğin nedenini not etti. Hatanın fark edilmesi, çalışmanın bütünüyle değersiz olduğu anlamına gelmiyordu. Kontrol edilebilir bir kayıt tuttuğu için hangi bilginin değişmesi gerektiğini bulabilmişti. Sonraki kontrollerde model adlarının yazımına daha fazla dikkat etti.\n\nSerginin açılışından önce ekip bir son kontrol listesi hazırladı. Nesnelerin güvenli şekilde yerleştirilmesi, yazıların rahat okunması ve dolaşım alanının açık kalması bu listede yer aldı. Eski radyonun çalıştırılması düşünülmedi; güvenliği uzman tarafından değerlendirilmemiş bir cihazı denemek serginin amacı değildi. Aras'ın kutusundaki araçlar da ziyaretçilerin gelişigüzel eline alabileceği biçimde bırakılmadı. Anlatının ilgi çekici olması kadar, insanların sergiyi güvenli ve erişilebilir biçimde gezebilmesi önemliydi. Ekip, tasarımın farklı ihtiyaçları birlikte gözetmesi gerektiğini konuştu.\n\nAçılış günü öğrenciler kendi nesnelerinin yanında nöbetleşe durdu. Bazı sorulara hemen cevap verebildiler, bazıları için kaynak dosyasına baktılar. Bilmedikleri bir ayrıntıyı tahmin ederek anlatmak yerine sonradan araştırabileceklerini söylediler. Defne ile Aras, ziyaretçilerin yeni bilgiler de getirdiğini gördü. Ancak yeni bir anıyı duyduklarında sergi kartını hemen değiştirmediler; önce onu kaydettiler. Çalışmaları, eşyalara kesin ve değişmez anlamlar veren bir gösteri olmaktan çıkmıştı. Nesnelerin farklı insanlar için farklı hatıralar taşıyabileceğini ve bu çeşitliliğin açık bir anlatımla sunulabileceğini fark ettiler.\n\nSergi bittiğinde yalnız fotoğraflar değil, taslaklar ve düzenleme notları da bir araya getirildi. Gelecek yıl aynı projeyi yapacak öğrenciler, son metnin kendiliğinden oluşmadığını görebilecekti. Her çıkarılan cümle, değiştirilen başlık ve düzeltilen kaynak bilgisi bir kararın izini taşıyordu. Defne, araştırma yapmanın yalnız bilgi bulmak olmadığını düşündü. Bilginin sınırlarını tanımak, izinleri gözetmek ve farklı okuyuculara anlaşılır biçimde sunmak da aynı çalışmanın parçalarıydı. Aras ise artık eski bir kutuya baktığında yalnız araçları değil, onu anlatmak için sorulabilecek iyi soruları da görüyordu."},{"id":"61000000-0000-4000-8000-000000000009","exerciseId":"551b174b-71b2-5b0d-aa99-4b04c1a16829","age":"Teen","level":2,"title":"Sınırsız Dünya / Kendin Ol","sources":[{"id":"698b13f9-aa55-4c9f-b8d3-dbee20565293","title":"Sınırsız Dünya","wordCount":288,"contentHash":"3a9f931dd04017798ad29803d34979a7"},{"id":"c43eea6c-f5b9-4055-8727-0765c2e8d79a","title":"Kendin Ol","wordCount":288,"contentHash":"899c81f18316b73914d1b4dcf967926b"}]},{"id":"61000000-0000-4000-8000-000000000010","exerciseId":"551b174b-71b2-5b0d-aa99-4b04c1a16829","age":"Teen","level":2,"title":"Sessiz Kahraman / İkinci Şans","sources":[{"id":"4dd0a78f-2741-4779-bfa1-3df7929e606e","title":"Sessiz Kahraman","wordCount":296,"contentHash":"41d964cd756d51c7a759444912da3695"},{"id":"f1a5f5b1-52ad-4939-96ac-62f08ca09372","title":"İkinci Şans","wordCount":297,"contentHash":"5f36bca3d767415b572887ce4dc119bf"}]},{"id":"61000000-0000-4000-8000-000000000011","exerciseId":"62b339c7-cf1c-5ece-819f-3c24e00e93a7","age":"Teen","level":3,"title":"Biyomimetik: Doğadan İlham / Karbon Ayak İzi: Bir Molekülün Günlüğü","sources":[{"id":"0b323669-e098-44