ler Kaderimiz Değildir / Start-up Kültürü: Garajdan Milyar Dolara","sources":[{"id":"4a1b2c3d-8e9f-4444-bbbb-123456789012","title":"Epigenetik: Genler Kaderimiz Değildir","wordCount":425,"contentHash":"1789314d4505da73ca88013f0ed900a5"},{"id":"11223344-5566-7788-9900-aabbccddeeff","title":"Start-up Kültürü: Garajdan Milyar Dolara","wordCount":518,"contentHash":"9103fd592890d377f418b554417d2e48"}]},{"id":"61000000-0000-4000-8000-000000000016","exerciseId":"79e32c19-71ce-5f68-802e-588d3d3b7182","age":"YoungAdult","level":4,"title":"Dijital Minimalizm: Gürültülü Dünyada Odaklanma / Uzaktan Çalışma ve Dijital Göçebelik: Ofissiz Hayat","sources":[{"id":"abcdef01-2345-6789-aaaa-bbbbccccdddd","title":"Dijital Minimalizm: Gürültülü Dünyada Odaklanma","wordCount":439,"contentHash":"8c71ac7dd1b2024b0671220a6411718b"},{"id":"77889900-1122-3344-5566-778899001122","title":"Uzaktan Çalışma ve Dijital Göçebelik: Ofissiz Hayat","wordCount":510,"contentHash":"bad7c30090d393656b7f09210bc77674"}]},{"id":"61000000-0000-4000-8000-000000000017","exerciseId":"a3533513-6a35-5037-ad55-ae51942c437f","age":"YoungAdult","level":5,"title":"Kuantum Dolanıklık: \"Ürkütücü\" Bir Mesafe / Entropi ve Zamanın Oku: Kaosun Yasası","sources":[{"id":"44556677-8899-0011-2233-445566778899","title":"Kuantum Dolanıklık: \"Ürkütücü\" Bir Mesafe","wordCount":491,"contentHash":"7bbf1dd517227d6aad9f2b5a5c78dbfd"},{"id":"1c2d3e4f-5a6b-7777-8888-666677778888","title":"Entropi ve Zamanın Oku: Kaosun Yasası","wordCount":559,"contentHash":"902e574beaa3876462f98e161b91c4ef"}]},{"id":"61000000-0000-4000-8000-000000000018","exerciseId":"a3533513-6a35-5037-ad55-ae51942c437f","age":"YoungAdult","level":5,"title":"Simbiyoz ve İşbirliği: Doğanın Gizli Kanunu / Sicim Teorisi: Evrenin En Küçük Melodisi","sources":[{"id":"88990011-2233-4455-6677-889900112233","title":"Simbiyoz ve İşbirliği: Doğanın Gizli Kanunu","wordCount":502,"contentHash":"c99db3304fea8382fac04341577388f4"},{"id":"3c4d5e6f-7a8b-9999-0000-bbbbccccdddd","title":"Sicim Teorisi: Evrenin En Küçük Melodisi","wordCount":549,"contentHash":"f7fd45eb9dc496231c623af53ecee648"}]},{"id":"61000000-0000-4000-8000-000000000019","exerciseId":"a744fd23-45f3-51cf-ac18-85f81d094937","age":"Adult","level":1,"title":"Patron mu, Lider mi? Modern Liderlik Anlayışı / Sürdürülebilirlik ve Sıfır Atık: Gezegen İçin Bir Yaşam Tarzı","sources":[{"id":"e952de08-a9c2-456d-b911-83d422b2625b","title":"Patron mu, Lider mi? Modern Liderlik Anlayışı","wordCount":365,"contentHash":"92e370020d1637a3ad93b39548bcde80"},{"id":"813ec134-d8e3-4a2c-b65a-62ef4372dec8","title":"Sürdürülebilirlik ve Sıfır Atık: Gezegen İçin Bir Yaşam Tarzı","wordCount":374,"contentHash":"3f0ace7bf4f778333a38d265bd8b00f6"}]},{"id":"61000000-0000-4000-8000-000000000020","exerciseId":"a744fd23-45f3-51cf-ac18-85f81d094937","age":"Adult","level":1,"title":"Patron mu, Lider mi? Modern Liderlik Anlayışı / Yalnız Seyahat Sanatı: Kendini Yolda Bulmak","sources":[{"id":"e952de08-a9c2-456d-b911-83d422b2625b","title":"Patron mu, Lider mi? Modern Liderlik Anlayışı","wordCount":365,"contentHash":"92e370020d1637a3ad93b39548bcde80"},{"id":"da3a87e9-30ce-43ce-80ca-e42850cade83","title":"Yalnız Seyahat Sanatı: Kendini Yolda Bulmak","wordCount":380,"contentHash":"5b6e3f9eeaeb07dd5f2acc675889b8ed"}]},{"id":"61000000-0000-4000-8000-000000000021","exerciseId":"9546695f-5d8b-5857-8e8d-b431e37224e5","age":"Adult","level":2,"title":"Enflasyon Canavarı ve Faiz Silahı: Makroekonomi 101 / Geleceğin Parası mı, Dijital Lale Çılgınlığı mı: Kripto Paralar ve Blockchain","sources":[{"id":"370b80a5-12c9-4f29-a568-e7762af601f2","title":"Enflasyon Canavarı ve Faiz Silahı: Makroekonomi 101","wordCount":363,"contentHash":"273332bd0229d265d511502daeec12ab"},{"id":"1d0be83a-59a5-4026-b3e7-f331c8818c44","title":"Geleceğin Parası mı, Dijital Lale Çılgınlığı mı: Kripto Paralar ve Blockchain","wordCount":443,"contentHash":"e71dcc2262e0af3a2b29f13e4d7d1468"}]},{"id":"61000000-0000-4000-8000-000000000022","exerciseId":"9546695f-5d8b-5857-8e8d-b431e37224e5","age":"Adult","level":2,"title":"Sanayi Devriminin Dördüncü Dalgası: Endüstri 4.0 ve İşin Geleceği / Homo Economicus Efsanesi: Davranışsal İktisat ve İrrasyonelliğimiz","sources":[{"id":"aecc0af5-30d1-4e06-85e3-026a8281a5ad","title":"Sanayi Devriminin Dördüncü Dalgası: Endüstri 4.0 ve İşin Geleceği","wordCount":376,"contentHash":"48f0be90012bf2a7e44493a89554910b"},{"id":"e1b39f90-37b3-4c06-84c7-54b048496528","title":"Homo Economicus Efsanesi: Davranışsal İktisat ve İrrasyonelliğimiz","wordCount":422,"contentHash":"34cbd585ccb0f8ca3a4a6e72dca32002"}]}]$content$::jsonb) item;
DO $$ BEGIN
 IF (SELECT count(*) FROM guided_patch)<>20 OR (SELECT count(DISTINCT id) FROM guided_patch)<>20 THEN
  RAISE EXCEPTION 'Expected twenty distinct guided reading settings';
 END IF;
 IF (SELECT count(*) FROM speed_reading.exercises e JOIN guided_patch p ON e.id=p.id
  WHERE e.type_code='SpeedReading' AND e.target_age_group_id=p.age_id AND e.difficulty_level=p.level
   AND e.title=p.title AND e.is_active AND NOT e.is_deleted)<>20 THEN
  RAISE EXCEPTION 'Guided reading exercise identity/status changed';
 END IF;
 IF (SELECT count(*) FROM speed_reading.exercises WHERE type_code='SpeedReading' AND is_active AND NOT is_deleted
  AND target_age_group_id IN(SELECT age_id FROM guided_patch))<>20 THEN
  RAISE EXCEPTION 'Unexpected duplicate guided reading exercise';
 END IF;
 IF EXISTS(SELECT 1 FROM speed_reading.exercises e JOIN guided_patch p ON e.id=p.id
  WHERE e.configuration_json IS DISTINCT FROM p.previous_config AND e.configuration_json IS DISTINCT FROM p.new_config) THEN
  RAISE EXCEPTION 'Guided reading source settings changed';
 END IF;
 IF (SELECT count(*) FROM guided_content_payload)<>22
  OR (SELECT count(DISTINCT item->>'id') FROM guided_content_payload)<>22 THEN
  RAISE EXCEPTION 'Expected twenty-two distinct content additions';
 END IF;
 IF EXISTS(SELECT 1 FROM guided_content_payload c
  LEFT JOIN guided_patch p ON p.id=(c.item->>'exerciseId')::uuid
  WHERE p.id IS NULL OR p.level<>(c.item->>'level')::int) THEN
  RAISE EXCEPTION 'Content addition targets an unreviewed exercise';
 END IF;
 IF EXISTS(SELECT 1 FROM guided_content_payload c
  CROSS JOIN LATERAL jsonb_array_elements(c.item->'sources') s
  JOIN guided_patch p ON p.id=(c.item->>'exerciseId')::uuid
  LEFT JOIN speed_reading.reading_texts t ON t.id=(s->>'id')::uuid
  WHERE t.id IS NULL OR NOT t.is_active OR t.is_deleted OR t.exercise_id IS NOT NULL
   OR t.target_age_group_id IS DISTINCT FROM p.age_id OR t.difficulty_level<>p.level
   OR t.language<>'tr' OR t.word_count<>(s->>'wordCount')::int
   OR t.word_count<>cardinality(regexp_split_to_array(btrim(t.content), E'\\s+'))
   OR md5(t.content)<>s->>'contentHash') THEN
  RAISE EXCEPTION 'Reviewed source text changed or is missing';
 END IF;
END $$;
CREATE TEMP TABLE guided_additions ON COMMIT DROP AS
SELECT (c.item->>'id')::uuid id, p.id exercise_id, p.age_id, p.level,
 c.item->>'title' title,
 COALESCE(c.item->>'content', (
  SELECT string_agg(t.content, E'\n\n' ORDER BY source.ordinality)
  FROM jsonb_array_elements(c.item->'sources') WITH ORDINALITY source(item, ordinality)
  JOIN speed_reading.reading_texts t ON t.id=(source.item->>'id')::uuid
 )) content,
 (p.new_config->'engineConfig'->'content'->>'minWordCount')::int minimum,
 (p.new_config->'engineConfig'->'content'->>'maxWordCount')::int maximum
FROM guided_content_payload c JOIN guided_patch p ON p.id=(c.item->>'exerciseId')::uuid;
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM guided_additions WHERE content IS NULL OR btrim(content)=''
  OR cardinality(regexp_split_to_array(btrim(content), E'\\s+')) NOT BETWEEN minimum AND maximum
  OR length(title)>300) THEN
  RAISE EXCEPTION 'Content addition violates text band/title limits';
 END IF;
 IF EXISTS(SELECT 1 FROM guided_additions a JOIN speed_reading.reading_texts t ON t.id=a.id
  WHERE t.content IS DISTINCT FROM a.content OR t.title IS DISTINCT FROM a.title
   OR t.target_age_group_id IS DISTINCT FROM a.age_id OR t.difficulty_level<>a.level
   OR t.exercise_id IS DISTINCT FROM a.exercise_id OR NOT t.is_active OR t.is_deleted
   OR t.tags<>'guided-reading-v1') THEN
  RAISE EXCEPTION 'Content identifier collision or existing pack text was edited';
 END IF;
END $$;
CREATE TEMP TABLE guided_before ON COMMIT DROP AS
SELECT e.* FROM speed_reading.exercises e JOIN guided_patch p ON e.id=p.id;
INSERT INTO speed_reading.reading_texts
 (id,title,content,word_count,category,difficulty_level,target_age_group_id,language,is_active,tags,
 recommended_min_level,recommended_max_level,average_comprehension_score,times_read,average_reading_time_seconds,
 exercise_id,created_at,created_by,version,is_deleted)
SELECT id,title,content,cardinality(regexp_split_to_array(btrim(content), E'\\s+')),
 'guided_reading',level,age_id,'tr',true,'guided-reading-v1',level,level,0,0,0,exercise_id,
 now(),'system:guided-reading-v1',0,false FROM guided_additions
ON CONFLICT(id) DO NOTHING;
UPDATE speed_reading.exercises e SET configuration_json=p.new_config,
 updated_at=now(),updated_by='system:guided-reading-v1',version=e.version+1
FROM guided_patch p WHERE e.id=p.id AND e.configuration_json IS DISTINCT FROM p.new_config;
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM guided_patch p WHERE (
  SELECT count(*) FROM speed_reading.reading_texts t WHERE t.is_active AND NOT t.is_deleted
   AND t.difficulty_level=p.level AND (t.target_age_group_id=p.age_id OR t.target_age_group_id IS NULL)
   AND (t.exercise_id=p.id OR t.exercise_id IS NULL) AND btrim(t.content)<>''
   AND t.word_count BETWEEN (p.new_config->'engineConfig'->'content'->>'minWordCount')::int
    AND (p.new_config->'engineConfig'->'content'->>'maxWordCount')::int
 )<2) THEN
  RAISE EXCEPTION 'Each guided reading age/level must have at least two eligible texts';
 END IF;
 IF EXISTS(SELECT 1 FROM speed_reading.exercises e JOIN guided_before b ON e.id=b.id
  WHERE (to_jsonb(e)-ARRAY['configuration_json','updated_at','updated_by','version'])
   IS DISTINCT FROM (to_jsonb(b)-ARRAY['configuration_json','updated_at','updated_by','version'])) THEN
  RAISE EXCEPTION 'Unexpected changes outside guided reading settings/audit';
 END IF;
END $$;
COMMIT;
